\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Parchment Color Theme ──
\definecolor{primary}{HTML}{3E2723}       % deep brown/ink
\definecolor{secondary}{HTML}{D35400}     % burnt orange
\definecolor{accent}{HTML}{8B1A1A}        % deep red
\definecolor{bgposter}{HTML}{F5F0E6}      % warm parchment
\definecolor{redbg}{HTML}{FFF3EE}         % warm red tint
\definecolor{goldbg}{HTML}{FFF8F0}        % warm gold tint
\definecolor{darkbg}{HTML}{F5EDE8}        % warm brown tint
\definecolor{redtitlebg}{HTML}{FDE5D8}    % warm orange title bar
\definecolor{goldtitlebg}{HTML}{FCE4C8}   % warm gold title bar
\definecolor{darktitlebg}{HTML}{E8DCD0}   % clay title bar
\definecolor{textdark}{HTML}{2C1810}
\definecolor{textgray}{HTML}{5D4037}
\definecolor{stathighlight}{HTML}{FEE8E0}
\definecolor{clay}{HTML}{E8D5C4}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{secondary!70!black},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{secondary!70!black},
    coltitle=secondary!70!black, colbacktitle=goldtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!70!black!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══ TITLE BAR (rows 1-3, span=2) ═══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{76}\selectfont\bfseries The History of Books}\\[8pt]
  {\fontsize{32}{40}\selectfont From Manuscripts to Mass Production}\\[6pt]
  {\fontsize{22}{30}\selectfont\color{white!65} A Data-Driven Journey Across 1,500 Years of Written Knowledge}
}

% ═══ HERO VISUALIZATION (rows 3-11.5, span=2) ═══
\posterbox[
  enhanced, colback=bgposter, arc=0pt, boxrule=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  halign=center, valign=center,
]{name=hero, column=1, span=2, between=row3 and row11}{
  \posterfig{0.98}{figures/dual_timeline.png}{Book Production: Manuscripts (left) vs. Printed Books (right). The Gutenberg press (dashed line, \raisebox{-0.5pt}{\textasciitilde}1440) marks the most dramatic inflection point in the history of knowledge dissemination.}
}

% ═══ STAT BANNER (rows 11-13, span=2) ═══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=5pt, bottom=5pt,
  valign=center, borderline south={2pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row11 and row13}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{primary} $\sim$1,440}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} Gutenberg's Printing Press}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 10}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} Centuries of Manuscript Data}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} 16M+}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} Printed Books by 2000 CE}\vspace{5pt}%
    }}
  \end{minipage}
}

% ═══ LEFT COLUMN: Manuscript Era + Modern Publishing (rows 13-17) ═══
\posterbox[redcard, title={The Manuscript Era (6th--15th C.)}
]{name=manuscripts, column=1, between=row13 and row16}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{$\sim$300} manuscripts in 6th century; \textbf{$\sim$48,000} by 15th
    \item Carolingian Renaissance (9th C.) spurred modest growth
    \item Rise of universities (12th C.) accelerated production
    \item Books remained \textbf{luxury items} for clergy and elites
    \item Each manuscript hand-copied over months or years
  \end{itemize}
  \vspace{2mm}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{\centering\vspace{4pt}
    {\fontsize{22}{28}\selectfont\bfseries\color{secondary!80!black}
    Slow trickle: $\sim$1,000 years to reach $\sim$50,000 manuscripts}\vspace{4pt}%
  }}
}

\posterbox[goldcard, title={Modern Publishing \& Consumption}
]{name=modern, column=1, between=row16 and row19}{
  \posterfig{0.96}{figures/modern_publishing.png}{New book titles per million people, selected countries. Source: Fink-Jensen (2015), IISH.}
  \vspace{1mm}
  \fontsize{22}{28}\selectfont
  \colorbox{secondary!15}{\parbox{0.94\linewidth}{\centering\vspace{2pt}
    Per-capita publishing varies \textbf{50$\times$} between countries, reflecting
    differences in literacy, income, and education systems.}\vspace{2pt}}
}

% ═══ RIGHT COLUMN: Gutenberg Revolution + Books as Mirror (rows 13-19) ═══
\posterbox[darkcard, title={The Gutenberg Revolution (\raisebox{-1pt}{\textasciitilde}1440)}
]{name=gutenberg, column=2, between=row13 and row16}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Printing press \textbf{replaced hand-copying} with movable type
    \item Production costs fell \textbf{dramatically}; books became accessible
    \item First 50 years: $\sim$15,000 printed editions in Europe
    \item Enlightenment (18th C.): output surged with rising literacy
    \item Industrial printing (19th C.): \textbf{mass production} began
  \end{itemize}
  \vspace{2mm}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{\centering\vspace{4pt}
    {\fontsize{22}{28}\selectfont\bfseries\color{primary}
    From elite luxury $\rightarrow$ mass commodity in $\sim$400 years}\vspace{4pt}%
  }}
}

\posterbox[highlightcard, title={Books as a Mirror of Society}
]{name=mirror, column=2, between=row16 and row19}{
  \fontsize{24}{32}\selectfont\color{primary!85!black}
  \vspace{2mm}
  \textbf{Literacy} — Book output tracks reading ability across populations.\\
  \textbf{Income \& Wealth} — Affordable books signal rising prosperity.\\
  \textbf{Education} — School systems drive demand for published works.\\
  \textbf{Culture \& Religion} — Early output dominated by religious texts;\\
  \hspace*{6pt} secular works grew with the Enlightenment.\\
  \vspace{2mm}
  {\fontsize{22}{28}\selectfont\itshape
  ``Book production is one of the most powerful proxies for\\ human development across centuries.''}
  \vspace{3mm}
  \colorbox{white!40}{\parbox{0.94\linewidth}{\centering\vspace{3pt}
    {\fontsize{22}{28}\selectfont\bfseries\color{primary!90!black}
    The transition from manuscript to print reshaped civilization.}\vspace{3pt}%
  }}
}

% ═══ FOOTER: Sources (rows 19-20, span=2) ═══
\posterbox[
  enhanced, colback=primary!8!white, arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=6pt, bottom=6pt,
  halign=left, valign=center,
  borderline north={1.5pt}{0pt}{primary!30},
]{name=footer, column=1, span=2, between=row19 and bottom}{
  \fontsize{18}{24}\selectfont\color{textgray}
  \textbf{Sources:} Buringh, E. \& Van Zanden, J.L. (2009). ``Charting the Rise of the West.'' \textit{Journal of Economic History}, 69(2). \quad
  Fink-Jensen, J. (2015). IISH Data Collection. \quad
  Roser, M. \& Ritchie, H. (2023). ``Books.'' \textit{Our World in Data}. CC BY.
  \hfill {\fontsize{16}{22}\selectfont Data visualization poster \textbar\ 2026}
}

\end{tcbposter}
\end{document}

